package ir.orix.school.assessment.api;
import java.math.BigDecimal; import java.time.Instant; import java.util.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import ir.orix.school.assessment.application.AssessmentService; import ir.orix.school.assessment.domain.*; import ir.orix.school.shared.security.CurrentUser;
@RestController @RequestMapping("/api/v1/assessment")
public class AssessmentController {
 private final AssessmentService service; public AssessmentController(AssessmentService service){this.service=service;}
 @GetMapping("/questions") @PreAuthorize("hasAuthority('QUESTION_READ')") public List<AssessmentService.QuestionView> questions(){return service.questions(CurrentUser.tenantId());}
 @PostMapping("/questions") @PreAuthorize("hasAuthority('QUESTION_WRITE')") public AssessmentService.QuestionView question(@Valid @RequestBody QuestionRequest r){return service.createQuestion(CurrentUser.tenantId(),CurrentUser.accountId(),new AssessmentService.QuestionCommand(r.courseId(),r.code(),r.type(),r.prompt(),r.options(),r.correctAnswers(),r.explanation(),r.defaultPoints()));}
 @PostMapping("/questions/{id}/versions") @PreAuthorize("hasAuthority('QUESTION_WRITE')") public AssessmentService.QuestionView version(@PathVariable Long id,@Valid @RequestBody VersionRequest r){return service.createVersion(CurrentUser.tenantId(),CurrentUser.accountId(),id,new AssessmentService.VersionCommand(r.prompt(),r.options(),r.correctAnswers(),r.explanation(),r.defaultPoints()));}
 @GetMapping("/assessments") @PreAuthorize("hasAuthority('ASSESSMENT_READ')") public List<AssessmentService.AssessmentView> assessments(){return service.assessments(CurrentUser.tenantId(),CurrentUser.membershipId(),CurrentUser.accountId());}
 @PostMapping("/assessments") @PreAuthorize("hasAuthority('ASSESSMENT_WRITE')") public AssessmentService.AssessmentView assessment(@Valid @RequestBody AssessmentRequest r){return service.createAssessment(CurrentUser.tenantId(),CurrentUser.accountId(),new AssessmentService.AssessmentCommand(r.courseId(),r.code(),r.title(),r.type(),r.opensAt(),r.closesAt(),r.durationMinutes(),r.attemptsAllowed(),r.randomizeQuestions(),r.priceRial()==null?0:r.priceRial()));}
 @PostMapping("/assessments/{id}/sections") @PreAuthorize("hasAuthority('ASSESSMENT_WRITE')") public AssessmentService.AssessmentView section(@PathVariable Long id,@Valid @RequestBody SectionRequest r){return service.addSection(CurrentUser.tenantId(),CurrentUser.accountId(),id,new AssessmentService.SectionCommand(r.title(),r.instructions(),r.sequenceNumber()));}
 @PostMapping("/assessments/{id}/questions") @PreAuthorize("hasAuthority('ASSESSMENT_WRITE')") public AssessmentService.AssessmentView attach(@PathVariable Long id,@Valid @RequestBody AttachQuestionRequest r){return service.addQuestion(CurrentUser.tenantId(),CurrentUser.accountId(),id,new AssessmentService.AssessmentQuestionCommand(r.sectionId(),r.questionVersionId(),r.points(),r.sequenceNumber()));}
 @PostMapping("/assessments/{id}/targets") @PreAuthorize("hasAuthority('ASSESSMENT_WRITE')") public AssessmentService.AssessmentView target(@PathVariable Long id,@Valid @RequestBody TargetRequest r){return service.addTarget(CurrentUser.tenantId(),CurrentUser.membershipId(),CurrentUser.accountId(),id,r.classSectionId());}
 @PostMapping("/assessments/{id}/publish") @PreAuthorize("hasAuthority('ASSESSMENT_PUBLISH')") public AssessmentService.AssessmentView publish(@PathVariable Long id){return service.publish(CurrentUser.tenantId(),CurrentUser.membershipId(),CurrentUser.accountId(),id);}
 @GetMapping("/me") public List<AssessmentService.MyAssessmentView> mine(){return service.mine(CurrentUser.tenantId(),CurrentUser.membershipId());}
 public record QuestionRequest(Long courseId,@NotBlank @Size(max=60) String code,@NotNull Question.Type type,@NotBlank String prompt,List<@NotBlank String> options,List<@NotBlank String> correctAnswers,String explanation,@NotNull @DecimalMin("0.01") BigDecimal defaultPoints){} public record VersionRequest(@NotBlank String prompt,List<@NotBlank String> options,List<@NotBlank String> correctAnswers,String explanation,@NotNull @DecimalMin("0.01") BigDecimal defaultPoints){}
 public record AssessmentRequest(Long courseId,@NotBlank @Size(max=60) String code,@NotBlank @Size(max=200) String title,@NotNull Assessment.Type type,@NotNull Instant opensAt,@NotNull Instant closesAt,@Min(1) int durationMinutes,@Min(1) int attemptsAllowed,boolean randomizeQuestions,@Min(0) Long priceRial){} public record SectionRequest(@NotBlank @Size(max=200) String title,String instructions,@Min(1) int sequenceNumber){} public record AttachQuestionRequest(@NotNull Long sectionId,@NotNull Long questionVersionId,@NotNull @DecimalMin("0.01") BigDecimal points,@Min(1) int sequenceNumber){} public record TargetRequest(@NotNull Long classSectionId){}
}
